package main
import("context";"errors";"log/slog";"os";"time";"github.com/jackc/pgx/v5";"github.com/flowpilot/flowpilot/internal/engine";"github.com/flowpilot/flowpilot/internal/storage")
func main(){ctx:=context.Background();s,e:=storage.Open(ctx,os.Getenv("DATABASE_URL"));if e!=nil{slog.Error("database unavailable","error",e);os.Exit(1)};defer s.Close();worker:="worker-"+os.Getenv("HOSTNAME");tick:=time.NewTicker(500*time.Millisecond);defer tick.Stop();for range tick.C {id,e:=s.Claim(ctx,worker);if errors.Is(e,pgx.ErrNoRows){continue};if e!=nil{slog.Error("claim failed","error",e);continue};slog.Info("executing","execution_id",id);g,input,e:=s.LoadExecutionGraph(ctx,id);if e==nil{eResult:=error(nil);var result map[string]any;result,eResult=engine.Run(ctx,g,input,func(node,kind string,p map[string]any){s.Event(ctx,id,node,kind,p)});e=s.Finish(ctx,id,result,eResult)}else{e=s.Finish(ctx,id,nil,e)};if e!=nil{slog.Error("finish failed","error",e)}}}
